/* Cyberpunk Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="cyberpunk-light"] {
  --background: rgb(248, 248, 248);
  --foreground: rgb(11, 10, 30);
  --card: rgb(255, 255, 255);
  --card-foreground: rgb(11, 10, 30);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(11, 10, 30);
  --primary: rgb(254, 0, 199);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(240, 240, 255);
  --secondary-foreground: rgb(11, 10, 30);
  --muted: rgb(240, 240, 255);
  --muted-foreground: rgb(11, 10, 30);
  --accent: rgb(32, 254, 204);
  --accent-foreground: rgb(11, 10, 30);
  --destructive: rgb(252, 63, 9);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(222, 230, 234);
  --input: rgb(222, 230, 234);
  --ring: rgb(254, 0, 199);
  --chart-1: rgb(254, 0, 199);
  --chart-2: rgb(144, 13, 253);
  --chart-3: rgb(0, 228, 253);
  --chart-4: rgb(32, 254, 204);
  --chart-5: rgb(255, 231, 41);
  --radius: 0.5rem;
  --sidebar: rgb(240, 240, 255);
  --sidebar-foreground: rgb(11, 10, 30);
  --sidebar-primary: rgb(254, 0, 199);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(32, 254, 204);
  --sidebar-accent-foreground: rgb(11, 10, 30);
  --sidebar-border: rgb(222, 230, 234);
  --sidebar-ring: rgb(254, 0, 199);
  --font-sans: Outfit, sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: Fira Code, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.1;
  --shadow-blur: 8px;
  --shadow-spread: -2px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 2px 4px -3px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 4px 6px -3px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 8px 10px -3px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 4px 8px -2px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="cyberpunk-dark"] {
  --background: rgb(11, 10, 30);
  --foreground: rgb(235, 239, 245);
  --card: rgb(29, 29, 61);
  --card-foreground: rgb(235, 239, 245);
  --popover: rgb(29, 29, 61);
  --popover-foreground: rgb(235, 239, 245);
  --primary: rgb(254, 0, 199);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(29, 29, 61);
  --secondary-foreground: rgb(235, 239, 245);
  --muted: rgb(29, 29, 61);
  --muted-foreground: rgb(127, 132, 165);
  --accent: rgb(32, 254, 204);
  --accent-foreground: rgb(11, 10, 30);
  --destructive: rgb(252, 63, 9);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(47, 47, 93);
  --input: rgb(47, 47, 93);
  --ring: rgb(254, 0, 199);
  --chart-1: rgb(254, 0, 199);
  --chart-2: rgb(144, 13, 253);
  --chart-3: rgb(0, 228, 253);
  --chart-4: rgb(32, 254, 204);
  --chart-5: rgb(255, 231, 41);
  --radius: 0.5rem;
  --sidebar: rgb(11, 10, 30);
  --sidebar-foreground: rgb(235, 239, 245);
  --sidebar-primary: rgb(254, 0, 199);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(32, 254, 204);
  --sidebar-accent-foreground: rgb(11, 10, 30);
  --sidebar-border: rgb(47, 47, 93);
  --sidebar-ring: rgb(254, 0, 199);
  --font-sans: Outfit, sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: Fira Code, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.1;
  --shadow-blur: 8px;
  --shadow-spread: -2px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 2px 4px -3px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 4px 6px -3px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 8px 10px -3px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 4px 8px -2px hsl(0 0% 0% / 0.25);
}
